head.script:
scwin.scheduleCalendar1_onclick = function(retObj) {
    //alert("retObj==" + JSON.stringify(retObj));
	console.log("retObj==" + JSON.stringify(retObj));
};
scwin.trigger1_onclick = function(e) {
    var num = progressbar1.get() + 10;
    progressbar1.set(num);
};
scwin.trigger2_onclick = function(e) {
    var num = progressbar1.get() - 10;
    progressbar1.set(num);
};
scwin.trigger4_onclick = function(e) {
    var jsonData1 = [{
            "colTitle": "타이틀 12345",
            "colEnd": "20171115090000",
            "colId": "id_111",
            "colStart": "2017-11-10"
        },
        {
            "colTitle": "타이틀 67890",
            "colEnd": "20171117090000",
            "colId": "id_112",
            "colStart": "2017-11-13"
        },
        {
            "colTitle": "타이틀 0000",
            "colEnd": "2017-11-22",
            "colId": "id_221",
            "colStart": "2017-11-22"
        },
        {
            "colTitle": "타이틀 1111",
            "colEnd": "2017-11-22",
            "colId": "id_222",
            "colStart": "2017-11-22"
        },
        {
            "colTitle": "타이틀 2222",
            "colEnd": "2017-11-22",
            "colId": "id_223",
            "colStart": "2017-11-22"
        }
    ];
    dataList1.setJSON(jsonData1);
};
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.clickMonth = function() {
    var date1 = new Date(2017, 11);
    var date2 = new Date();
    var month = (date2 - date1) / 86400000;
    for (i = 0; i < Math.floor(month / 30) + 1; i++) {
        WebSquare.wUnit.getJq(".fc-prev-button").click();
    }
}

scwin.setVal1 = function() {
    WebSquare.wUnit.getObjById('scheduleCalendar1').gotoCalendar("20171101", {noSelectable : true})
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getObjById('dataList1').getAllJSON()[0].colEnd == '20171116090000';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getObjById('dataList1').getAllJSON()[0].colStart == '20171110080000';
}

scwin.checkVal3 = function() {
    return dataList1.getAllJSON()[0].colEnd == '20171115090000';
}
scwin.checkVal4 = function() {
    return dataList1.getAllJSON()[0].colStart == '2017-11-10';
}
scwin.checkVal5 = function() {
    return dataList1.getAllJSON()[1].colEnd == '20171117090000';
}
scwin.checkVal6 = function() {
    return dataList1.getAllJSON()[1].colStart == '2017-11-13';
}

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "500");
	//WebSquare.wUnit.addCommand("set", "scwin.clickMonth()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
